import sys

def find_root(parent, i):
    while parent[i] != i:
        i = parent[i]
    return i

def union(nroot, parent, rank, a, b):
    aroot = find_root(parent, a)
    broot = find_root(parent, b)

    if aroot == broot:
        return
    if rank[aroot] < rank[broot]:
        parent[aroot] = broot
    elif rank[aroot] > rank[broot]:
        parent[broot] = aroot
    else:
        parent[broot] = aroot
        rank[aroot] += 1

def make_tree(edges):
    parent = [i for i in range(0, len(edges) + 1)]
    rank = [1 for i in range(len(edges) + 1)]
    for i, edge in enumerate(edges):
        union(parent, i, rank, edge[0], edge[1])
    return parent

def query(adj, nroot, rank, i):
    result = float('inf')
    closest = float('-inf')
    for j in range(i, len(adj)):
        root = find_root(adj, j)
        subtreesize = len(adj[root]) if root != nroot else len(adj) - 1
        if rank[root] + subtreesize < result:
            result = min(result, rank[root] + subtreesize)
            closest = adj[root]
    return result, adj[closest]

def solve(edges, ts, vs):
    tree = make_tree(edges)
    results = []
    for i in vs:
        result, nearest = query(tree, i, ts[i] - 1, tree.index(i))
        results.append(str(result))
