from heapq import heappush, heappop
from math import inf

def dijkstra(graph, start):
    distances = {}
    for i in range(1, n + 1):
        distances[i] = inf
    distances[start] = 0
    pq = [(0, start)]
    while pq:
        cost, node = heappop(pq)
        if cost > distances[node]:
            continue
        for neighbor in graph[node]:
            alternative_cost = cost + 1  # Flip the edge once
            if alternative_cost < distances[neighbor]:
                distances[neighbor] = alternative_cost
                heappush(pq, (alternative_cost, neighbor))
    return distances

