        n -= 1
    start, grandStart = 1, 1
    for a in d:
        sumWithLand = start * (a + 1) + grandStart * (a + 1 - start)
        sumWithoutLand = grandStart * a + start * (a + a + 2)
        if sumWithLand >= n:
            stack.append(sumWithLand - n + 2)
        sumWithLand -= grandStart * (a + 1 - start + 1)
        choPos = (a + 2) // 2
