from collections import defaultdict

def doe_graph(n):
    if n == 0:
        return defaultdict(lambda: 1)
    elif n == 1:
        return defaultdict(lambda: 1, {1: 1})

    edge = {n: (n-1, n, n+1)}

    # Start constructing the graph
    visited = set()
    stack = [(next(iter(doe_graph(n-1).keys() + doe_graph(n-2).keys())), dict(doe_graph(n-1), start=next(iter(doe_graph(n-1).keys()))))]

    while stack:
        parent, child = stack.pop()

        if parent in visited:
            continue
        visited.add(parent)

        # Add parent and recurse
        for edge, end in list(child.items()):
            if end == next(iter(doe_graph(n-1).keys())):
                edge = (parent, end)
        stack.append((parent, child | edge))

        # Add child and recurse
        for has_next in doe_graph(n-1).values():
            if has_next == edge[1]:
                node = (edge[1], {next(iter(doe_graph(n-2).keys())): end, edge[1]: set()})

                if node not in child:
                    stack.append((has_next, node))

    for child in sorted(child.keys(), reverse=True):
        child.update([end for has_next, end in child.items() if has_next != child]);

    return child

