from math import gcd
from itertools import permutations

def lcm(x, y):
    return x * y // gcd(x, y)

def cross_product_segment(segment, point):
    x1, y1 = point
    x2, y2 = segment
    return (x2 - x1) * (y1 - y2) - (y2 - y1) * (x1 - x2)

def divide_polygon_segments(n, points):
    segments = []
    for i in range(n):
        x1, y1 = points[i]
        x2, y2 = points[(i + 1) % n]
        segments.append((x1, y1, x2, y2))
    return segments

def check_approximation(segments, left_triangle_segments, right_triangle_segments):
    left_sum = all(cross_product_segment(segment, left_triangle_segments[i]) <= 1 for segment in segments)
    right_sum = all(cross_product_segment(segment, right_triangle_segments[i]) < 0 for segment in segments)
    area_approximation = 1 if left_sum and right_sum else 0
    return area_approximation

def divide_polygonIntoMatchCirclesAtMost3(n, points, approximation_func):
    segments = divide_polygon_segments(n, points)
    max_one_point_intersections = max(len([approximation_func(segment, segments[i]) for i in range(n)]) for i in range(n))
    return max_one_point_intersections * gcd(3, n) * (n // 2)

def solve(n, points):
    points = tuple(map(tuple, points))
    start, result = hull = (0, 0), 0
    points2 = tuple(n + i for i in range(n))

    for point in hull:
        point_index = i = next((rep for (rep, num) in enumerate(points) if num == point - start), -1)
        rep, _ = hull
        n += point_index - rep if point_index > rep else len(points2) - (point_index - rep)

    for cnt in range(n, 0, -1):
        result += n // gcd(n, cnt) * (cnt - 1)
    return result % (10**9 + 7)
