def is_good_suffix(s, current_suffix, character, max_diff, count, sorted_char_list):
    suffix_substring_start = count
    last_char_index = sorted_char_list.index(character)
    for i in range(last_char_index + 1, len(sorted_char_list)):
        next_char = sorted_char_list[i]
        if character in current_suffix and next_char not in current_suffix:
            if max_diff + 1 > i - last_char_index:
                return False
        else:
            suffix_substring_start += 1
        if suffix_substring_start >= len(s):
            break
        added_char = s[suffix_substring_start]
        if next_char in character:
            count += Counter(added_char)[next_char]
            if i == len(sorted_char_list) - 1:
                break
        elif next_char not in character and added_char not in character:
            count -= 1
        else:
            return False
    return True

def find_good_permutation(s, k):
    sorted_characters = sorted(set(s))
    if len(sorted_characters) == 1:
        return ''.join(sorted_characters[0] * len(s))

    for count in range(len(sorted_characters), 0, -1):
        for combination in combinations(sorted_characters, count):
            if all(is_good_suffix(s, ''.join(combination), character, k, count, sorted_characters) for character in combination):
                return ''.join(combination)
    return -1

