def compute_subdivisions(n, vertices):
    from math import gcd
    from functools import reduce

    def combine_divisors(d1, d2):
        if d1 == 1 or d2 == 1:
            return (1, d1 * d2)
        else:
            common_div = gcd(d1, d2)
            return (common_div, d1 // common_div * d2 // common_div)

    divisors = [g for _, g in groupby(sorted(int(divisor) for x, y in vertices for divisor in [x, y]) if divisor != 1)]
    return reduce(combine_divisors, divisors)

