def find_max_games(fans: List[int], n: int) -> int:
    dp = [0] * (1 << n)
    dp[1] = 1

    for mask in range(1, 1 << n):
        count = bin(mask).count('1')
        if count & 1:
            dp[mask] = int('1' * count, 2) + int(bin(mask).replace('0', '1', count).replace('1', '0', count), 2)
        else:
            dp[mask] = int('1' * count, 2)

    return dp[(1 << n) - 1 if n == 1 else (1 << n) - 1 ^ (1 << (n - 1))]
