    def add_schedule(follower, leader):
        if follower == 'not_found':
            return
        games[2 * follower - 1] = '0'
        schedules[leader].append(follower)
        add_schedule(leader, find_team(leader, games))

    add_schedule('not_found', find_team(0, games))
    full_hist = True
    total_games = 0

