def generate_doe_graph(order):
    if order == 0:
        return [(1,)]
    elif order == 1:
        return [(1, 2)]
    elif order == 2:
        return [(1, "e1"), (2, "e2"), (1, "e2", "c1"), (2, "e1", "c2")]

    edges_from_previous = generate_doe_graph(order - 1)
    e1 = edges_from_previous[-1][-1]
    edges_from_previous[-1] = [(0, e1)]

    edges_from_current = generate_doe_graph(order - 2)
    e2 = edges_from_current[-1][-1]

    return [(0, e1), (1, "e2"), (2, "e1"), (0, "e2", e1)]

def bfs_shortest_path(graph, start, end):
    visited = [False] * (len(graph) + 1)
    distance = [float("inf")] * (len(graph) + 1)
    queue = [start]

    distance[start] = 0
    while queue:
        curr = queue.pop(0)
        if curr == end:
            return distance[end]
        visited[curr] = True
        for neighbor, weight in graph[curr]:
            if not visited[neighbor] and (distance[neighbor] == float("inf") or distance[neighbor] > (distance[curr] + weight)):
