import sys

def doe_graph(n):
    if n == 0:
        return [[1]]
    elif n == 1:
        return [[1], [1, 2]]
    else:
        result = [[1, 2]]
        for i in range(2, n):
            new_vertex = result[-1][-1] + 1
            edge = [i, i + 1, 1]
            result.append(edge + result[-1] + result[-1][1:-1] + [new_vertex])
        result.append(result[-1][1: -1] + [result[-1][-1] + result[-1][-1]])
        return result

def shortest_path_distance(doe_graph, n):
    if n < len(doe_graph):
        return n
    elif n == len(doe_graph):
        return 1
    else:
        prev_vertex = len(doe_graph) - 1
        current_vertex = n - len(doe_graph) + 1
        min_distance = float('inf')
        for i in range(len(doe_graph) - 1):
            if current_vertex in doe_graph[i] or prev_vertex in doe_graph[i]:
                continue
            distance = len(doe_graph[:i]) + 1 + n
            if distance < min_distance:
                min_distance = distance
        return min_distance

def solve(t, n):
    for _ in range(t):
        ai, bi = map(int, input().split())
        print(shortest_path_distance(doe_graph, bi - 1) - shortest_path_distance(doe_graph, ai - 1))

if __name__ == "__main__":
    t, n = map(int, input().split())
    doe_graph = doe_graph(n)
    solve(t, n)
