import sys
from collections import deque

def hamming_distance(s: str, t: str, index: int, length: int) -> int:
    count = 0
    for i in range(index, index + length):
        if s[i] != t[i]:
            count += 1
    return count

class SegmentTree:
    def __init__(self, size: int):
        self.size = size
        self.tree = [[0,0] for _ in range(4 * size + 1)]
        self.build_tree()

    def build_tree(self):
        for i in range(1, len(self.tree)):
            self.tree[i] = self.tree[i // 2][0] + self.tree[i // 2][1], max(self.tree[i // 2][0], self.tree[i // 2][1])

    def update(self, index: int, length: int, value: int):
        self.res[index + length][0] += value
        self.increment(index + length, length)

    def increment(self, index: int, length: int):
        while index < len(self.res):
            self.res[index][0] += length
            self.res[index][0] %= 2**62
            index += index & -index

    def query(self, left: int, right: int) -> int:
        st, en = 0, len(self.tree)
        ans = 0
        left += len(self.tree)
        right += len(self.tree)
        while left < right:
            end = max(left, right)

            if end % 2 == 1:
                ans += self.res[end // 2][0]
                end += 1
            left += 1
            if end - 1 < len(self.tree):
                end -= 1
                ans += self.res[end // 2][0]
            right -= 1
        return ans

def main():
    a = sys.argv[1]
    b = sys.argv[2]
    queries = int(sys.stdin.readline())

    res = SegmentTree(len(a) + len(b) + 2)
    for i in range(queries):
        idx, p1, p2 = map(int, sys.stdin.readline().split())
        p1 += len(a)
        p2 += len(b)
        print(res.query(p1, p2), end=' ')

if __name__ == "__main__":
    main()
