import random
import math

def expected_tax(N, edges):
    # Filter out roads that are already paired
    edges = set([tuple(sorted(edge)) for edge in edges])

    # Calculate the expected toll tax
    expected_tax = 0
    for i in range(N):
        for j in range(i + 1, N):
            if (i, j) not in edges:
                for pair in list(edges):
                    if i in pair and j in pair:
                        expected_tax += min(pair)
                        break
                else:
                    expected_tax += 1
    return expected_tax / N

