from itertools import cycle

def find_approaches(prefix, ciphers, keys):
    approaches = [[0 for _ in range(len(prefix))] for _ in range(len(ciphers))]
    def check_c(s):
        for p in cycle(keys):
            yield sum(a*b%mod for a, b in zip(s, prefix))
    for i, ch in enumerate(ciphers):
        for a in check_c(ch):
            approaches[i][0] = pow(a, mod-2, mod)
    for shift in range(1, len(ciphers)):
        shiftmod = shift * (len(prefix) // shift)
        for i in range(len(ciphers)):
            for j in range(shift, len(ciphers)):
                approaches[i][shift] += approaches[i][j-shift]
                approaches[i][shift] = pow( approaches[i][shift], mod-2, mod)
    ans = []
    margin = min([min(approaches[i]) % mod for i in range(len(ciphers))])
    for i in range(len(ciphers)):
        a = [sum(approaches[i][j]*v%mod for j,v in enumerate(prefix)) % mod for v in keys]
        if all([sum(a) % mod == c % mod ** shiftmod % mod for c, v in zip(ch, keys)]) and a[0] % mod != 0:
            a[0] -= margin // keys[i]
            if any([((x-a[0]) % mod < 0) for x in a]):
                ans.append(tuple(a))
    ans.sort()
    return ans

if __name__ == "__main__":
    mod = int(input().strip())
    key = cycle(range(0, mod))
    nums = tuple(map(int, input().strip().split()))
    knowns = tuple(map(int, input().strip().split()))
    print(len(find_approaches(nums, knowns, key)))
    [print(tuple(knowns)) for known in knoweds]
