from math import gcd

def lcm(a, b):
    return a * b // gcd(a, b)

def find_sequence(length, b, c):
    possible_sequences = []
    for a in product(range(n), repeat=length):
        current_ci = 0
        for i in range(length):
            current_ci += c[(i + index(i)) % length] * a[i]
        if abs(current_ci) > 10**12:  # Assuming integer arithmetic precision
            break
        if potential_quadratic_residual_test(b, a):
            potential_quadratic_residual_test(c, a)
            possible_sequences.append(list(a))
    return possible_sequences

def potential_quadratic_residual_test(b, a):
    for x in range(1, max(abs(b[0]), abs(a[0])) // 2 + 1):
        if b[0] * x**2 == b[0] * x - a[0]:
            return False
    return True

